scope = ''.join(f'<tr><th scope="row">{e(row[0])}</th><td>{e(row[1])}</td><td>{e(row[2])}</td></tr>' for row in d['scope'])
bullets = lambda values: '<ul>' + ''.join(f'<li>{e(x)}</li>' for x in values) + '</ul>'
p = d['precedent']
links = ''.join(f'<li><a href="{p["repository"]}/blob/{p["commit"]}/{s["path"]}" target="_blank" rel="noopener noreferrer">{e(s["name"])}</a> <small>源码行 {e(s["lines"])}</small></li>' for s in p['sources'])
page = r'''<!doctype html><html lang="zh-CN"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>历史研究 · 广义非攻击威力（已停止）</title><style>
:root{--bg:#f7f1e6;--surface:#fffcf6;--border:#d7c7af;--text:#302820;--text-dim:#706454;--red:#96372c;--sage:#476752;--gold:#986419}*{box-sizing:border-box}html{scroll-behavior:smooth}body{margin:0;background:var(--bg);color:var(--text);font:16px/1.85 "Microsoft YaHei UI","PingFang SC",sans-serif}a{color:var(--red);text-underline-offset:4px}.wrap{max-width:1260px;margin:auto;padding:30px 32px 70px;display:grid;grid-template-columns:145px minmax(0,1fr);gap:35px}.toc{position:sticky;top:24px;align-self:start}.toc b{font:12px Consolas,monospace;letter-spacing:.1em;color:var(--text-dim)}.toc a{display:block;padding:10px 0;border-bottom:1px solid var(--border);text-decoration:none;font-size:13px}.main{min-width:0}header{padding:14px 0 30px;border-bottom:3px solid var(--text)}.eyebrow,.num{font:12px Consolas,monospace;letter-spacing:.1em;color:var(--gold)}h1,h2,h3{font-family:"Noto Serif SC","Source Han Serif SC",SimSun,serif;line-height:1.4}h1{font-size:clamp(34px,4.1vw,52px);margin:18px 0}h1 em{color:var(--red);font-style:normal}h2{font-size:28px;margin:10px 0 18px}h3{font-size:21px;margin:10px 0}.lead{font-size:19px}.status{font-size:12px;color:var(--red);border:1px solid var(--red);display:inline-block;padding:2px 9px}.section{padding:34px 0;border-bottom:1px solid var(--border);scroll-margin-top:25px}p{margin:12px 0}.two{display:grid;grid-template-columns:1fr 1fr;gap:25px}.two>*{min-width:0}.rule{padding:23px 27px;background:#362822;color:#fff3e0;font-size:22px;font-family:"Noto Serif SC",SimSun,serif}.notice{border-left:4px solid var(--red);padding:15px 21px;background:#ede3d3;margin:20px 0}.notice p{margin:0}.muted,small{color:var(--text-dim)}.table-wrap{overflow-x:auto;border:1px solid var(--border);margin:20px 0}table{width:100%;border-collapse:collapse;font-size:14px;background:var(--surface)}thead{background:#ece2d2}th,td{text-align:left;padding:13px 15px;vertical-align:top;border-bottom:1px solid var(--border);overflow-wrap:break-word}th:first-child{width:29%}td:nth-child(2){white-space:nowrap}caption{padding:10px 15px;text-align:left;color:var(--text-dim)}li{margin:10px 0}ul{padding-left:23px}.panel{border:1px solid var(--border);padding:23px 26px;background:var(--surface)}label{display:block;font-size:15px}input{accent-color:var(--red)}input[type=range]{width:100%;margin:18px 0}.numbers{display:grid;grid-template-columns:1fr 1fr 1fr;gap:18px}.numbers>div{min-width:0;border-top:2px solid var(--border);padding:14px 0}.numbers strong{font:39px/1.5 Consolas,monospace;color:var(--red)}.numbers small{display:block;font-size:12px}.numbers b{font-size:14px}.numbers p{font-size:13px}.formula{font-family:Consolas,"Microsoft YaHei UI",monospace}.tag{font-size:12px;color:var(--sage)}details{border:1px solid var(--border);background:var(--surface);padding:15px 20px;margin:20px 0}summary{cursor:pointer;font-weight:600}a:focus-visible,summary:focus-visible,input:focus-visible{outline:3px solid var(--gold);outline-offset:4px}footer{font-size:12px;color:var(--text-dim);padding-top:25px}
@media(max-width:900px){.wrap{grid-template-columns:1fr;gap:10px;padding:0 22px 45px}.toc{display:flex;gap:18px;z-index:2;top:0;white-space:nowrap;overflow:auto;background:var(--bg);border-bottom:1px solid var(--border)}.toc b{display:none}.toc a{border:0;font-size:12px}.section{scroll-margin-top:60px}}
@media(max-width:600px){.two,.numbers{grid-template-columns:1fr}.wrap{padding:0 18px 35px}.table-wrap table{min-width:640px}.rule{font-size:19px;padding:20px}.panel{padding:20px}h1{font-size:35px}h2{font-size:25px}.numbers{gap:2px}.numbers p{margin:3px 0}}
@media(prefers-reduced-motion:reduce){html{scroll-behavior:auto}}</style></head><body><div class="wrap"><nav class="toc" aria-label="章节"><b>MEGUMIN / MIGHT</b><a href="#verdict">设计判断</a><a href="#scope">生效范围</a><a href="#frequency">频率与强度</a><a href="#precedent">已实现的先例</a><a href="#integration">惠惠如何承接</a><a href="#technical">实现边界</a></nav><main class="main"><header><span class="eyebrow">MECHANIC REVIEW · 2026.10.09</span><h1>力量增强攻击，<br><em>威力增强非攻击伤害。</em></h1><p class="lead">@@VERDICT@@</p><span class="status">历史评估 · 方向已停止 · 未实装</span></header>
<section class="section" id="verdict"><span class="num">01 / DESIGN JUDGMENT</span><h2>这个分工比“仅强化爆裂”更值得试</h2><div class="two"><div><h3>概念容易解释</h3><p>力量与威力各自覆盖一种伤害类别。普通攻击仍有自己的成长手段，爆裂、持续效果、反伤和其他间接输出则有共同的伤害投资。</p><p>威力的主要职责就是提高伤害，不依赖先把格挡、积蓄或弃牌数量兑换成输出。</p></div><div><h3>能容纳不同兑现节奏</h3><p>同一份威力可以支持一次大爆裂、分次触发、跨回合持续输出，以及遗物带来的偶发伤害。玩家获得更多选择伤害载体的空间。</p><p>不过当前自家非攻击输出若仍只有爆裂，单纯扩大说明文字还不足以增加构筑变化。</p></div></div><p class="rule">@@RULE@@</p><p class="muted">建议按每次实际伤害平加一次，正常跨回合保留、战后清零。中文“威力”在这里是Mod机制名；此前核对的原作“爆发系魔法威力上升”并不等于所有非攻击伤害都增强。</p></section>
<section class="section" id="scope"><span class="num">02 / SCOPE</span><h2>“所有”应当落实到可解释的伤害范围</h2><p>判断伤害本身的类别，而不是只看卡牌类型。攻击牌施加的毒，之后的毒伤仍可属于非攻击；反过来，没有吃到力量的特殊攻击，也不能一概当成非攻击。</p><div class="table-wrap"><table><caption>以下是推荐口径，尚未成为当前规则</caption><thead><tr><th>来源</th><th>威力</th><th>关键边界</th></tr></thead><tbody>@@SCOPE@@</tbody></table></div><div class="notice"><p><b>不要双算。</b>对中毒，只增强每次毒伤，不再额外增加施毒层数；对黑暗球，只在放出造成伤害时增强，不把蓄存阶段也增强。格挡、回复和生命支付也不因为来自“非攻击牌”而吃威力。</p></div></section>
<section class="section" id="frequency"><span class="num">03 / FREQUENCY IS THE MULTIPLIER</span><h2>最大的风险：高频小伤害更容易放大威力</h2><p>每点威力的总收益取决于实际伤害次数和目标数。这个性质与力量强化多段攻击相似，但持续效果、反伤和遗物有时不必再支付一张攻击牌的费用，因此不能直接照抄力量的投放量。</p><div class="panel"><label for="might">威力：<b id="might-value">3</b> <span class="muted">拖动比较三种伤害结构</span></label><input type="range" id="might" min="0" max="8" value="3"><div class="numbers" aria-live="polite"><div><b>一次20伤害</b><p><strong id="single">23</strong></p><small>对单个目标；基础总伤害20</small><p class="formula" id="single-formula">20 + 3 = 23</p></div><div><b>四次5伤害</b><p><strong id="multi">32</strong></p><small>对同一个目标；基础总伤害同样20</small><p class="formula" id="multi-formula">4 × (5 + 3) = 32</p></div><div><b>3层毒自然结算完</b><p><strong id="poison">15</strong></p><small>三次3→2→1；基础总伤害6</small><p class="formula" id="poison-formula">6 + 3 × 3 = 15</p></div></div><p class="muted">这是规则算例，不是强度排名：假定目标存活、没有其他增减伤，毒无新增层数或加速触发，威力保持不变。前三项均只计算一个目标。</p></div><p>3点威力让同为20基础伤害的两种结构分别增加3与12。群伤还会对每个命中目标分别增加；如果持续效果能额外触发，收益也会随次数增长。</p><div class="notice"><p><b>爆裂的主题需要主动照顾。</b>可以比较较低的威力投放、受控的触发频率，以及让少量配套牌提高爆裂的威力系数。不要任由所有最优构筑都转向小额自动伤害，使招牌爆裂只剩下开关作用。</p></div></section>
<section class="section" id="precedent"><span class="num">04 / VERIFIED PRECEDENT</span><h2>确实有直接先例：Replay the Spire 的「专家」</h2><span class="tag">杀戮尖塔一代 · 作者公开源码已核对</span><p>@@CARD_FACTS@@</p><p>@@IMPLEMENTATION@@</p><p>@@LESSON@@</p><ul>@@LINKS@@</ul><p class="muted">核对提交：<code>da9c945</code>，2024-08-28；检索日期2026-10-09。@@COVERAGE@@</p><details><summary>这个先例能证明什么？</summary><p>它证明“统一提高非攻击伤害”是已经写进Mod代码并注册了卡牌的机制，不只是玩家讨论中的设想。它不证明我们的卡池可以直接采用同样数值，也不证明所有第三方伤害都能无条件兼容。</p><p>本轮先由玩家讨论定位名称，再以作者仓库的卡牌、伤害补丁、本地化和注册代码交叉核对。论坛评论中具体的跨Mod失效案例只作线索，没有作为实测结果引用。</p></details></section>
<section class="section" id="integration"><span class="num">05 / FITTING MEGUMIN</span><h2>我建议保留这个方向，重新做输出载体与数值</h2>@@BALANCE@@<p>魔力积蓄继续负责准备手牌；威力负责伤害成长；爆裂负责一次明确的兑现。若后续补充其他非攻击输出，也应先设计它们何时造成伤害、需要付出什么，再考虑题材命名。</p><p>爆裂回合末伤害可先按“N + 威力”比较，即一次吟唱只吃一次；多倍威力应由明确配套效果提供。原先回流一击的直接攻击仍按攻击伤害处理，不能因为牌有自行入区效果而改变分类。</p><p><b>当前尚未把这个方向写成已采用规则。</b>尤其爆裂的伤害类型、联机毒伤归属与新威力的投放量，需要先验证。</p></section>
<section class="section" id="technical"><span class="num">06 / IMPLEMENTATION BOUNDARIES</span><h2>二代可以借鉴思路，但不能只反转力量的判断</h2><p>本地v0.107.1源码中，力量根据伤害性质和来源判定。中毒、纠缠等伤害的调用却可能没有携带施加者；这是“你造成的所有非攻击伤害”在联机时需要解决的实际问题。</p><details><summary>已核对的技术边界与待验证项</summary>@@TECHNICAL@@</details><p>此外，增伤应直接进入本次伤害计算，保留原本的格挡、无实体等防御结算；不要额外补打一段伤害来模拟威力，以免改变触发次数。</p><div class="notice"><p><b>建议的最小验证范围：</b>攻击与非攻击互斥；爆裂单次加值；持续效果多次加值；群伤逐目标加值；毒层数不变；自身扣血不变；减伤有效；预览与实伤一致；联机来源不串算。</p></div><p class="muted">只做设计与源码研究，没有运行Mod或修改游戏。原核心文件内容@@CORE_STATE@@。</p><p><a href="惠惠伤害体系候选.html">上一轮：仅增强爆裂的候选</a> · <a href="原版五职业与Karen伤害体系分析.html">六职业伤害主轴参考</a> · <a href="docs/威力非攻击伤害评估.json">本轮结构化评估</a></p></section><footer>威力范围评估 · 原作题材与Mod规则分别标注 · 来源链接指向作者公开源码。</footer></main></div><script>
(()=>{const $=id=>document.getElementById(id);function update(){const p=Number($('might').value);$('might-value').textContent=p;$('single').textContent=20+p;$('multi').textContent=4*(5+p);$('poison').textContent=6+3*p;$('single-formula').textContent=`20 + ${p} = ${20+p}`;$('multi-formula').textContent=`4 × (5 + ${p}) = ${4*(5+p)}`;$('poison-formula').textContent=`6 + 3 × ${p} = ${6+3*p}`;}$('might').addEventListener('input',update);update();})();
</script></body></html>'''
core_hash = hashlib.sha256((HERE / '惠惠核心机制候选.json').read_bytes()).hexdigest()
replacements = {
    'VERDICT': e(d['verdict']), 'RULE': e(d['suggested_rule']), 'SCOPE': scope,
    'CARD_FACTS': e(p['card_facts']), 'IMPLEMENTATION': e(p['implementation']),
    'LESSON': e(p['lesson']), 'LINKS': links, 'COVERAGE': e(p['coverage_limit']),
    'BALANCE': bullets(d['balance']), 'TECHNICAL': bullets(d['sts2_implementation_notes']),
    'CORE_STATE': '未改' if core_hash == d['original_core_sha256'] else '已变化，需重新核对',
}
for key, value in replacements.items():
    page = page.replace('@@' + key + '@@', value)
assert '@@' not in page
out = HERE.parent / '惠惠威力机制评估.html'
out.write_text(with_design_notice(page, 'nonattack-reference'), encoding='utf-8')
print('Rendered non-attack damage assessment; original core unchanged:', core_hash == d['original_core_sha256'])
